"""Fixed seed catalog for the Omyshop product table. Shared by both backends
so the SQLite dev/test catalog and the Postgres prod catalog never drift:
engine.py's init_db() (SQLite) and migration 006 (Postgres) both insert this
same list. Fixed ids (not new_id()) so the insert is idempotent across
repeated calls/migrations, same pattern as omyfish-java's Flyway seed.

Six products use real CC-licensed/public-domain photos (resized + re-encoded
as inline base64 JPEG data URIs — self-contained, no external image hosting
needed, matching the placeholder approach's own design constraint). The
remaining two (no suitable free photo found) keep the inline SVG placeholder.
`image_credit` carries the required attribution for CC BY/BY-SA photos;
public-domain and placeholder entries leave it None."""

import base64


def _placeholder_svg(name: str, category: str, color: str) -> str:
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300">'
        f'<rect width="400" height="300" fill="{color}"/>'
        f'<text x="200" y="145" font-family="Arial, Helvetica, sans-serif" '
        f'font-size="26" font-weight="bold" fill="white" text-anchor="middle">{name}</text>'
        f'<text x="200" y="175" font-family="Arial, Helvetica, sans-serif" '
        f'font-size="18" fill="white" text-anchor="middle" opacity="0.85">{category}</text>'
        f'</svg>'
    )
    # Raw (non-base64) data URIs break here: the hex colors' "#" is parsed as
    # the URL fragment delimiter, truncating the SVG markup mid-attribute.
    encoded = base64.b64encode(svg.encode("utf-8")).decode("ascii")
    return f"data:image/svg+xml;base64,{encoded}"


